#include "VocalPanel.h"
namespace ssbb {
VocalPanel::VocalPanel(){title_.setText("3. Vocals",juce::dontSendNotification);title_.setFont(juce::FontOptions(17.0f,juce::Font::bold));text_.setMultiLine(true);text_.setTextToShowWhenEmpty("Type original lyrics...",juce::Colours::grey);energyLabel_.setText("Energy",juce::dontSendNotification);energy_.setRange(0,1,.01);energy_.setValue(.7);status_.setText("AI runs offline from the audio callback.",juce::dontSendNotification);status_.setColour(juce::Label::textColourId,juce::Colours::lightgrey);for(auto*c:{static_cast<juce::Component*>(&title_),&text_,&energyLabel_,&energy_,&generate_,&record_,&status_})addAndMakeVisible(c);generate_.onClick=[this]{if(onGenerate)onGenerate(text_.getText(),static_cast<float>(energy_.getValue()));};record_.onClick=[this]{if(onRecord)onRecord();};}
void VocalPanel::setStatus(const juce::String&s){status_.setText(s,juce::dontSendNotification);}void VocalPanel::paint(juce::Graphics&g){g.setColour(juce::Colour(0xff1b2030));g.fillRoundedRectangle(getLocalBounds().toFloat(),8);}void VocalPanel::resized(){auto r=getLocalBounds().reduced(10);title_.setBounds(r.removeFromTop(28));text_.setBounds(r.removeFromTop(92));auto e=r.removeFromTop(32);energyLabel_.setBounds(e.removeFromLeft(52));energy_.setBounds(e);generate_.setBounds(r.removeFromTop(34).reduced(2));record_.setBounds(r.removeFromTop(34).reduced(2));status_.setBounds(r);}
} // namespace ssbb
